336	  export default {
337	    private: {
338	      currentTime: '00:00',
339	      battery: 100,
340	      isMonitoring: true,
341	      todayData: {
342	        score: 85,
343	        goodPostureMinutes: 45,
344	        badPostureMinutes: 15,
345	        totalChecks: 12,
346	        reminders: 3,
347	        lastCheckTime: null
348	      },
349	      aiAdvice: '👍 今日体态良好，继续保持！',
350	      scorePercent: 85,
351	      scoreRotation: 0,
352	      checkTimer: null
353	    },
354	
355	    onInit() {
356	      this.updateTime()
357	      this.loadTodayData()
358	      this.startMonitoring()
359	      this.loadBattery()
360	    },
361	
362	    onDestroy() {
363	      this.stopMonitoring()
364	    },
365	
366	    // 更新时间
367	    updateTime() {
368	      setInterval(() => {
369	        const now = new Date()
370	        this.currentTime = `${String(now.getHours()).padStart(2, '0')}:${String(now.getMinutes()).padStart(2, '0')}`
371	      }, 1000)
372	    },
373	
374	    // 加载电量
375	    loadBattery() {
376	      battery.getStatus({
377	        success: (data) => {
378	          this.battery = data.level
379	        }
380	      })
381	    },
382	
383	    // 加载今日数据
384	    loadTodayData() {
385	      const app = this.$app
386	      if (app && app.globalData) {
387	        this.todayData = app.globalData.todayData
388	        this.updateScoreDisplay()
389	      }
390	    },
391	
392	    // 更新分数显示
393	    updateScoreDisplay() {
394	      this.scorePercent = this.todayData.score
395	      this.scoreRotation = (this.todayData.score / 100) * 360
396	
397	      // 更新AI建议
398	      if (this.todayData.score >= 90) {
399	        this.aiAdvice = '🎉 体态优秀！继续保持！'
400	      } else if (this.todayData.score >= 70) {
401	        this.aiAdvice = '👍 体态良好，还可以更好！'
402	      } else if (this.todayData.score >= 50) {
403	        this.aiAdvice = '⚠️ 体态一般，注意坐姿调整'
404	      } else {
405	        this.aiAdvice = '🚨 体态较差，请立即调整！'
406	      }
407	    },
408	
409	    // 开始监测
410	    startMonitoring() {
411	      const app = this.$app
412	      const interval = (app && app.globalData && app.globalData.settings.postureCheckInterval) || 30
413	
414	      // 模拟体态检测（实际项目中会调用传感器API）
415	      this.checkTimer = setInterval(() => {
416	        this.checkPosture()
417	      }, interval * 60 * 1000)
418	
419	      this.isMonitoring = true
420	    },
421	
422	    // 停止监测
423	    stopMonitoring() {
424	      if (this.checkTimer) {
425	        clearInterval(this.checkTimer)
426	        this.checkTimer = null
427	      }
428	      this.isMonitoring = false
429	    },
430	
431	    // 检查体态
432	    checkPosture() {
433	      // 模拟体态检测结果（实际项目中会分析传感器数据）
434	      const isGoodPosture = Math.random() > 0.3 // 70%概率良好体态
435	
436	      const app = this.$app
437	      if (app && app.updatePostureData) {
438	        app.updatePostureData(isGoodPosture)
439	        this.todayData = app.globalData.todayData
440	        this.updateScoreDisplay()
441	      }
442	
443	      // 不良体态时震动提醒
444	      if (!isGoodPosture) {
445	        this.vibrateDevice()
446	      }
447	    },
448	
449	    // 震动提醒
450	    vibrateDevice() {
451	      const app = this.$app
452	      const intensity = (app && app.globalData && app.globalData.settings.vibrationIntensity) || 'medium'
453	
454	      let duration = 100
455	      if (intensity === 'strong') duration = 200
456	      else if (intensity === 'light') duration = 50
457	
458	      vibrator.vibrate({ mode: 'short', duration: duration })
459	    },
460	
461	    // 显示AI建议
462	    showAIAdvice() {
463	      router.push({
464	        uri: '/pages/alert',
465	        params: {
466	          type: 'ai_advice',
467	          score: this.todayData.score
468	        }
469	      })
470	    },
471	
472	    // 手势处理
473	    handleSwipe(e) {
474	      if (e.direction === 'left') {
475	        router.push({ uri: '/pages/history' })
476	      } else if (e.direction === 'right') {
477	        router.push({ uri: '/pages/settings' })
478	      }
479	    },
480	
481	    // 导航方法
482	    goHome() {
483	      // 已在首页
484	    },
485	
486	    goHistory() {
487	      router.push({ uri: '/pages/history' })
488	    },
489	
490	    goSettings() {
491	      router.push({ uri: '/pages/settings' })
492	    }
493	  }
494	</script>
