    if (record.posture === 'good') {
      goodCount++
    } else {
      badCount++
    }

    postureCounts[record.posture] = (postureCounts[record.posture] || 0) + 1
  })

  // 找出最常见的体态
  let mostCommon = 'unknown'
  let maxCount = 0
  Object.entries(postureCounts).forEach(([posture, count]) => {
    if (count > maxCount) {
      maxCount = count
      mostCommon = posture
    }
  })

