/**
 * 获取有效历史记录数组（环形缓冲区 → 线性数组）
 */
getHistoryArray() {
  if (this.historyCount === 0) return []
  if (this.historyCount < 100) {
    return this.postureHistory.slice(0, this.historyCount)
  }
  // 环形缓冲区已满：从 historyIndex 开始读取（即最旧的元素）
  return this.postureHistory.slice(this.historyIndex).concat(
    this.postureHistory.slice(0, this.historyIndex)
  )
}

/**
 * 获取当前体态状态
 */
getCurrentPosture() {
  if (this.historyCount === 0) {
    return { posture: 'unknown', isGood: false }
  }

  // 最新元素在 historyIndex - 1 的位置
  const latestIndex = (this.historyIndex - 1 + 100) % 100
  const latest = this.postureHistory[latestIndex]
  return {
    posture: latest.posture,
    isGood: latest.posture === 'good',
    pitch: latest.pitch,
    roll: latest.roll
  }
}

/**
 * 获取体态统计
 */
getPostureStats() {
  if (this.historyCount === 0) {
    return {
      goodCount: 0,
      badCount: 0,
      goodPercent: 0,
      mostCommon: 'unknown'
    }
  }

  let goodCount = 0
  let badCount = 0
  const postureCounts = {}

  for (let i = 0; i < this.historyCount; i++) {
    const record = this.postureHistory[i]
    if (record.posture === 'good') {
      goodCount++
    } else {
      badCount++
    }
    postureCounts[record.posture] = (postureCounts[record.posture] || 0) + 1
  }

  // 找出最常见的体态
  let mostCommon = 'unknown'
  let maxCount = 0
  Object.entries(postureCounts).forEach(([posture, count]) => {
    if (count > maxCount) {
      maxCount = count
      mostCommon = posture
    }
  })

  return {
    goodCount,
    badCount,
    goodPercent: Math.round((goodCount / this.historyCount) * 100),
    mostCommon
  }
}

