/**
 * 获取本周的所有日期
 */
static getWeekDates() {
  const dates = []
  const now = new Date()
  const dayOfWeek = now.getDay()
  const start = new Date(now)
  start.setDate(now.getDate() - dayOfWeek + 1) // 周一
  const todayKey = this.getTodayKey()

  // 复用同一个 Date 对象，减少临时对象创建
  const d = new Date(start)
  for (let i = 0; i < 7; i++) {
    d.setDate(start.getDate() + i)
    const dateKey = this.format(d, 'YYYY-MM-DD')
    dates.push({
      date: dateKey,
      display: this.format(d, 'MM月DD日'),
      day: this.getDayOfWeek(d),
      isToday: dateKey === todayKey
    })
  }

  return dates
}

