    'good': '[良好] 良好坐姿',
    'leaning_forward': '[警告] 过度前倾',
    'leaning_back': '[警告] 过度后仰',
    'tilted': '[警告] 身体侧倾',
    'unknown': '[未知] 未知状态'
  }
  return descriptions[posture] || descriptions['unknown']
}

