/**
 * 体态守护 - 设计系统常量
 * 统一管理颜色、字体、间距等设计规范
 */

// 配色方案
export const colors = {
  // 主色调
  primary: '#3b82f6',       // 蓝色 - 主要操作、激活状态
  primaryDark: '#2563eb',   // 深蓝色 - 按下状态
  primaryLight: '#60a5fa',  // 浅蓝色 - 轻量强调

  // 功能色
  success: '#22c55e',       // 绿色 - 良好体态、完成
  successDark: '#16a34a',
  warning: '#f59e0b',       // 琥珀色 - 警告、不良体态
  warningDark: '#d97706',
  danger: '#ef4444',        // 红色 - 危险、停止
  dangerDark: '#dc2626',
  ai: '#8b5cf6',            // 紫色 - AI 相关
  aiDark: '#7c3aed',

  // 背景色
  bgPrimary: '#0f172a',     // 主背景 - 深蓝黑
  bgSecondary: '#1e293b',   // 次要背景 - 深灰
  bgTertiary: '#334155',    // 第三级背景 - 中灰
  bgCard: '#1e293b',        // 卡片背景
  bgCardHover: '#253347',   // 卡片悬停（渐变用）

  // 文字色
  textPrimary: '#ffffff',   // 主文字 - 白色
  textSecondary: '#94a3b8', // 次要文字 - 浅灰
  textTertiary: '#64748b',  // 第三级文字 - 灰色
  textMuted: '#475569',     // 弱化文字 - 深灰
  textInverse: '#0f172a',   // 反色文字 - 深色背景上的白字

  // 边框色
  borderLight: '#334155',   // 浅边框
  borderDark: '#1e293b',    // 深边框

  // 透明色
  transparent: 'transparent',
  overlay: 'rgba(0, 0, 0, 0.5)', // 遮罩层（注意：rgba 在部分设备可能不支持）
}

// 渐变色（仅垂直方向）
export const gradients = {
  // 背景渐变
  bgPrimary: 'linear-gradient(to bottom, #0f172a, #1a1a2e)',
  bgSecondary: 'linear-gradient(to bottom, #1e293b, #253347)',

  // 功能渐变
  success: 'linear-gradient(to bottom, #22c55e, #16a34a)',
  warning: 'linear-gradient(to bottom, #f59e0b, #d97706)',
  danger: 'linear-gradient(to bottom, #ef4444, #dc2626)',
  ai: 'linear-gradient(to bottom, #8b5cf6, #7c3aed)',
  primary: 'linear-gradient(to bottom, #3b82f6, #2563eb)',
}

// 字体大小
export const fontSize = {
  xs: 10,    // 极小 - 标签、角标
  sm: 12,    // 小 - 辅助文字
  base: 14,  // 基础 - 正文
  md: 16,    // 中等 - 小标题
  lg: 18,    // 大 - 标题
  xl: 22,    // 超大 - 页面标题
  xxl: 28,   // 特大 - 评分数字
  hero: 36,  // 主要 - 首页评分
}

// 字体粗细
export const fontWeight = {
  normal: 400,
  medium: 500,
  semibold: 600,
  bold: 700,
}

// 间距
export const spacing = {
  xs: 4,     // 极小间距
  sm: 8,     // 小间距
  md: 12,    // 中等间距
  base: 16,  // 基础间距
  lg: 20,    // 大间距
  xl: 24,    // 超大间距
  xxl: 32,   // 特大间距
}

// 圆角
export const borderRadius = {
  sm: 5,     // 小圆角 - 小按钮
  md: 8,     // 中圆角 - 输入框
  base: 12,  // 基础圆角 - 卡片
  lg: 16,    // 大圆角 - 大卡片
  xl: 20,    // 超大圆角 - 特殊卡片
  full: 999, // 全圆角 - 圆形按钮
}

// 阴影（注意：QuickApp 可能不支持 box-shadow）
export const shadows = {
  sm: '0 1px 2px rgba(0, 0, 0, 0.25)',
  md: '0 4px 6px rgba(0, 0, 0, 0.25)',
  lg: '0 10px 15px rgba(0, 0, 0, 0.25)',
}

// 图标尺寸
export const iconSize = {
  xs: 16,    // 极小 - 角标
  sm: 20,    // 小 - 导航图标
  md: 24,    // 中等 - 卡片图标
  lg: 32,    // 大 - 功能图标
  xl: 48,    // 超大 - 空状态图标
  xxl: 64,   // 特大 - 首页图标
}

// 动画时长
export const animation = {
  fast: 150,     // 快速 - 按钮反馈
  normal: 250,   // 正常 - 页面切换
  slow: 350,     // 慢速 - 展开收起
  slower: 500,   // 更慢 - 特殊动画
}

// 设备适配
export const device = {
  // 安全边距
  safePadding: {
    round: 0.08,   // 圆屏：屏幕宽度的 8%
    square: 20,    // 方屏：固定 20px
  },
  // 安全区域
  safeArea: {
    round: 0.10,   // 圆屏：高度的 10%
    square: 0,     // 方屏：无
  },
  // 最小触摸区域
  minTouchTarget: 44,
}

// 导航栏配置
export const navBar = {
  height: 44,
  iconSize: 36,
  titleSize: 18,
}

// 底部 Tab 栏配置
export const tabBar = {
  height: 56,
  iconSize: 24,
  labelSize: 10,
  activeColor: colors.primary,
  inactiveColor: colors.textTertiary,
}

// 卡片配置
export const card = {
  padding: 14,
  borderRadius: borderRadius.base,
  backgroundColor: colors.bgCard,
  gap: 8, // 卡片之间的间距
}

// 按钮配置
export const button = {
  height: {
    sm: 32,
    md: 40,
    lg: 48,
  },
  padding: {
    sm: 12,
    md: 16,
    lg: 20,
  },
  borderRadius: borderRadius.base,
}

// 徽章配置
export const badge = {
  height: 24,
  padding: 8,
  borderRadius: borderRadius.sm,
  fontSize: fontSize.xs,
}

// 颜色获取函数
export const getColorWithOpacity = (hexColor, opacity) => {
  // 注意：QuickApp 可能不支持 rgba，这个函数仅供参考
  // 在实际使用时，请使用预定义的透明色或 solid 颜色
  return hexColor
}

// 获取渐变背景
export const getGradientStyle = (gradientName) => {
  return {
    backgroundImage: gradients[gradientName] || gradients.bgPrimary,
  }
}

// 获取卡片样式
export const getCardStyle = (options = {}) => {
  return {
    backgroundColor: options.backgroundColor || colors.bgCard,
    borderRadius: options.borderRadius || borderRadius.base,
    padding: options.padding || card.padding,
  }
}

export default {
  colors,
  gradients,
  fontSize,
  fontWeight,
  spacing,
  borderRadius,
  shadows,
  iconSize,
  animation,
  device,
  navBar,
  tabBar,
  card,
  button,
  badge,
  getColorWithOpacity,
  getGradientStyle,
  getCardStyle,
}

/**
 * 体态守护 - 图标系统
 * 使用文字+样式组合模拟图标效果
 * 在不支持 SVG 的设备上提供最佳视觉效果
 */

