  default: '#64748b',

  // 功能色
  primary: '#3b82f6',
  success: '#22c55e',
  warning: '#f59e0b',
  danger: '#ef4444',
  ai: '#8b5cf6',

  // 状态色
  active: '#3b82f6',
  inactive: '#64748b',
  disabled: '#475569',
}

// 图标尺寸预设
export const iconSizes = {
  xs: { fontSize: 12, width: 16, height: 16 },
  sm: { fontSize: 14, width: 20, height: 20 },
  md: { fontSize: 16, width: 24, height: 24 },
  lg: { fontSize: 20, width: 32, height: 32 },
  xl: { fontSize: 24, width: 40, height: 40 },
  xxl: { fontSize: 28, width: 48, height: 48 },
  hero: { fontSize: 36, width: 64, height: 64 },
}

// 获取图标显示文本
export const getIconText = (iconType) => {
  return iconText[iconType] || '?'
}

// 获取图标样式
export const getIconStyle = (options = {}) => {
  const {
    size = 'md',
    color = 'default',
    backgroundColor = null,
    borderRadius = null,
  } = options

  const sizeConfig = iconSizes[size] || iconSizes.md
  const iconColor = iconColors[color] || iconColors.default

  const style = {
    fontSize: sizeConfig.fontSize,
    color: iconColor,
    width: sizeConfig.width,
    height: sizeConfig.height,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  }

  if (backgroundColor) {
    style.backgroundColor = backgroundColor
    if (borderRadius) {
      style.borderRadius = borderRadius
    } else {
      style.borderRadius = sizeConfig.width / 2
    }
  }

  return style
}

